from pathlib import Path
import sys,subprocess,json,hashlib,ast,mmap,ctypes,os,resource,time,random,struct
resource.setrlimit(resource.RLIMIT_CORE,(0,0))
r=Path("/home/qq/hia-native-integration-20261128-03da85-core/source");sys.path.insert(0,str(r));o=r.parent/"sha-scalar-cache-component-v1"
pre=r.parent/"outer240-published-d547421e-v1/fresh/cold.native-cold/preseed"
assembly=pre/"bootstrap/hia-seed-assembly";projector=pre/"bootstrap/hia-seed-projector"
backends={"old":pre/"products/seed-cold-endian-shift.tool","new":o/"candidate.backend-tool"}
from tools.generate_hia_cold_allocator_witness import document
from hepta.hia_agent_assembly import render_assembly
pins={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in [assembly,projector,*backends.values(),r/"examples/hia_bootstrap/cold_sha256_nonalias.hepta"]}
report={"schema":"hia.cold.scalar-cache.native-components.v1","source_head":"d547421e89c9d08cd5a85630018750ced2b332e8","scope":"old/new compiler scalar/CFG semantics and actual HIA SHA; no full qualification","passed":False,"input_pins":pins,"programs":[],"pairs":[],"sha_vectors":[],"sha_benchmarks":[],"host_exclusive":False}
report_path=o/"native-components-v2.json"
def save():report_path.write_text(json.dumps(report,indent=2,sort_keys=True)+"\n")
def invoke(exe,data,args=()):
 p=subprocess.run([str(exe),*args],input=data,capture_output=True,env={"PATH":"","LANG":"C"},timeout=30)
 if p.returncode or p.stderr or not p.stdout:raise ValueError((str(exe),p.returncode,p.stderr,p.stdout[:100]))
 return p.stdout
def projected(raw,label):
 core=invoke(assembly,raw,("--agent-compact",));wire=invoke(projector,b"["+core+b',"f0",1]');(o/(label+".projected")).write_bytes(wire);return wire
def callable(raw):
 mm=mmap.mmap(-1,len(raw),prot=mmap.PROT_READ|mmap.PROT_WRITE|mmap.PROT_EXEC);mm.write(raw)
 fn=ctypes.CFUNCTYPE(ctypes.c_uint64,ctypes.c_void_p,ctypes.c_uint64,ctypes.c_void_p,ctypes.c_uint64,ctypes.c_void_p,ctypes.c_uint64)(ctypes.addressof(ctypes.c_char.from_buffer(mm)))
 return fn,mm
def build(raw,label):
 wire=projected(raw,label);variants={};maps=[];sizes={}
 for kind,exe in backends.items():
  flat=invoke(exe,wire);(o/(label+"."+kind+".flat")).write_bytes(flat)
  fn,mm=callable(flat);variants[kind]=fn;maps.append(mm);sizes[kind]={"bytes":len(flat),"sha256":hashlib.sha256(flat).hexdigest()}
 return variants,maps,sizes
rng=random.Random(0x294173)
entry="""def entry(s:readbuf,o:mutbuf,w:mutbuf) -> u32:
    value = widen(calculate(word_load(s,0),word_load(s,8),word_load(s,16),word_load(s,24)))
"""
entry+="".join("    store(o,"+str(i)+",(value >> "+str(i*8)+") & 255)\n" for i in range(8))+"    return 8\n"
bodies={
"chain":"""    x = a + b
    y = x ^ c
    z = y & b
    q = z | c
    v = q - a
    t = v * b
    u = t >> d
    return (u ^ a) + c
""",
"branch":"""    if a < b:
        x = (a + b) ^ c
    else:
        x = (a - b) | c
    return (x + a) >> d
""",
"loop":"""    x = a
    i = 0
    while i < 4:
        x = (x + b) ^ c
        i = i + 1
    return (x - a) >> d
"""
}
bodies["right"]="""    x = a + b
    y = c ^ x
    z = b & y
    q = c | z
    v = a + q
    t = b * v
    u = t >> d
    return c + (a ^ u)
"""
bodies["compare"]="""    x = a + b
    equal = c == x
    different = a != x
    if equal and different:
        return (c ^ x) >> d
    return (x - c) >> d
"""
bodies["constants"]="    x = (a + b) + 3\n    y = x ^ 5\n    z = y | 7\n    v = z - a\n    return (v * c) >> d\n"
bodies["call"]="    x = a + b\n    y = identity(x)\n    return (y ^ c) >> d\n"
try:
 for width in (8,16,32,64):
  mask=(1<<width)-1
  selected=dict(bodies)
  if width!=64:del selected["constants"]
  if width==64:selected["mask"]="    x = (a + b) & 4294967295\n    return (x ^ c) >> d\n"
  for mode,body in selected.items():
   source=entry+"\ndef calculate(a:u"+str(width)+",b:u"+str(width)+",c:u"+str(width)+",d:u"+str(width)+") -> u"+str(width)+":\n"+body+"\ndef widen(value:u64) -> u64:\n    return value\n"
   if mode=="call":source+="\ndef identity(value:u"+str(width)+") -> u"+str(width)+":\n    return value\n"
   raw=render_assembly(document(source)).encode();label="scalar"+str(width)+"_"+mode;(o/(label+".hepta")).write_bytes(raw)
   variants,maps,sizes=build(raw,label);report["programs"].append({"name":label,"images":sizes})
   edge=[0,1,2,mask>>1,(mask>>1)+1,mask-1,mask]
   values=[(a,b,c,d) for a,b,c,d in [(0,0,0,0),(mask,mask,mask,width-1),(1,mask,1,width),(mask,1,mask,width+1)]]
   values += [(rng.choice(edge) if i<24 else rng.getrandbits(width),rng.choice(edge) if i<24 else rng.getrandbits(width),rng.getrandbits(width),rng.randrange(width)) for i in range(44)]
   for index,vals in enumerate(values):
    packet=ctypes.create_string_buffer(struct.pack("<5Q",*vals,0));observed=[]
    for kind,fn in variants.items():
     backing=mmap.mmap(-1,4096);backing.write(bytes((j*13+17)&255 for j in range(4096)));address=ctypes.addressof(ctypes.c_char.from_buffer(backing));pid=os.fork()
     if pid==0:
      if ctypes.CDLL(None).prctl(4,0,0,0,0)!=0:os._exit(125)
      result=fn(packet,40,address+64,64,address+1024,1024);struct.pack_into("<Q",backing,0,result);os._exit(0)
     _,status=os.waitpid(pid,0);observed.append((status,backing[:]));backing.close()
    if observed[0]!=observed[1]:raise ValueError(("native scalar/CFG mismatch",label,index,vals,observed[0][0],observed[1][0]))
    report["pairs"].append({"program":label,"case":index,"input_sha256":hashlib.sha256(packet.raw).hexdigest(),"status":observed[0][0],"entire_owner_sha256":hashlib.sha256(observed[0][1]).hexdigest()})
   for mm in maps:mm.close()
   save();print("SCALAR_CARRY_NATIVE_PROGRAM_PASS",label,len(report["pairs"]),json.dumps(sizes),flush=True)
 sha_raw=(r/"examples/hia_bootstrap/cold_sha256_nonalias.hepta").read_bytes();variants,maps,sizes=build(sha_raw,"actual_sha");report["sha_images"]=sizes
 def state():
  return ctypes.create_string_buffer(b"\xa7"*32,32),ctypes.create_string_buffer(b"\xc3"*1184,1184)
 def step(fn,data,output,workspace):
  packet=ctypes.create_string_buffer(data);before=packet.raw;rc=fn(packet,len(data),output,32,workspace,1184)
  if packet.raw!=before:raise ValueError("SHA changed read-only input")
  return int(rc),output.raw,workspace.raw
 lengths=[0,1,2,55,56,63,64,65,127,128,129,255,256,257,1000,4096,65535,65536,65537,1<<20]
 for index,n in enumerate(lengths):
  payload=rng.randbytes(n);contexts={kind:state() for kind in variants};chunks=[]
  pos=0
  while pos<n:
   step_size=min(n-pos,rng.choice([1,7,63,64,65,1024,65536]));chunks.append(payload[pos:pos+step_size]);pos+=step_size
  inputs=[b"\0",*[b"\1"+chunk for chunk in chunks],b"\2"];last=None
  for seq,data in enumerate(inputs):
   observed=[step(fn,data,*contexts[kind]) for kind,fn in variants.items()]
   if observed[0]!=observed[1]:raise ValueError(("actual SHA state differs",n,seq))
   last=observed[0]
  if last[0]!=32 or last[1]!=hashlib.sha256(payload).digest():raise ValueError(("SHA known digest differs",n,last[0],last[1].hex()))
  report["sha_vectors"].append({"bytes":n,"chunks":len(chunks),"digest":last[1].hex(),"final_state_sha256":hashlib.sha256(last[2]).hexdigest()})
  save()
 report["sha_arbitrary_states"]=[]
 for case in range(32):
  seed=rng.randbytes(1184);contexts={kind:(ctypes.create_string_buffer(b"\xa7"*32,32),ctypes.create_string_buffer(seed,1184)) for kind in variants}
  for _,work in contexts.values():
   struct.pack_into("<Q",work,1088,case)
   struct.pack_into("<Q",work,1096,case)
   struct.pack_into("<Q",work,1104,1)
   struct.pack_into("<Q",work,1176,3554263975777875528)
  inputs=[b"\1"+rng.randbytes(129+case),b"\2"]
  for seq,data in enumerate(inputs):
   observed=[step(fn,data,*contexts[kind]) for kind,fn in variants.items()]
   if observed[0]!=observed[1]:raise ValueError(("SHA full-u64 state differs",case,seq))
  report["sha_arbitrary_states"].append({"case":case,"rc":observed[0][0],"digest":observed[0][1].hex(),"workspace_sha256":hashlib.sha256(observed[0][2]).hexdigest()})
 save()
 print("SCALAR_CARRY_ACTUAL_SHA_VECTORS_PASS",len(report["sha_vectors"]),json.dumps(sizes),"arbitrary_states",len(report["sha_arbitrary_states"]),flush=True)
 payload=rng.randbytes(65536);block=ctypes.create_string_buffer(b"\1"+payload);init=ctypes.create_string_buffer(b"\0");final=ctypes.create_string_buffer(b"\2")
 expected=hashlib.sha256(payload*256).digest();reference=None
 for index,kind in enumerate(("old","new","new","old","old","new")):
  out,work=state();fn=variants[kind];start=time.monotonic_ns();cpu=time.process_time_ns()
  assert fn(init,1,out,32,work,1184)==0
  for _ in range(256):assert fn(block,65537,out,32,work,1184)==0
  assert fn(final,1,out,32,work,1184)==32
  row={"iteration":index,"variant":kind,"message_bytes":65536*256,"cpu_ns":time.process_time_ns()-cpu,"wall_ns":time.monotonic_ns()-start,"digest":out.raw.hex(),"workspace_sha256":hashlib.sha256(work.raw).hexdigest()}
  assert out.raw==expected
  if reference is None:reference=(out.raw,work.raw)
  else:assert reference==(out.raw,work.raw)
  report["sha_benchmarks"].append(row);save();print("SCALAR_CARRY_SHA_BENCH",json.dumps(row),flush=True)
 for mm in maps:mm.close()
 for p,d in pins.items():assert hashlib.sha256(Path(p).read_bytes()).hexdigest()==d
 report["passed"]=True;save();print("SCALAR_CARRY_ALL_NATIVE_PASS",len(report["pairs"]),len(report["sha_vectors"]),flush=True)
except BaseException:
 import traceback
 report["error"]=traceback.format_exc();save();raise
